package com.geekmall.trade;

import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.geekmall.common.api.BusinessException;import com.geekmall.common.domain.DistributedId;import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@Service class OrderService{
 private final JdbcTemplate jdbc;private final CheckoutService checkout;private final InventoryClient inventory;private final TradeEventStore events;private final ObjectMapper mapper;private final TransactionTemplate tx;private final long timeoutSeconds;private final MarketingClient marketing;private final MemberClient member;private final SeckillOrderService seckillOrders;
 OrderService(JdbcTemplate jdbc,CheckoutService checkout,InventoryClient inventory,TradeEventStore events,ObjectMapper mapper,PlatformTransactionManager manager,MarketingClient marketing,MemberClient member,SeckillOrderService seckillOrders,@Value("${geek.order-timeout-seconds:1800}")long timeoutSeconds){this.jdbc=jdbc;this.checkout=checkout;this.inventory=inventory;this.events=events;this.mapper=mapper;this.tx=new TransactionTemplate(manager);this.marketing=marketing;this.member=member;this.seckillOrders=seckillOrders;this.timeoutSeconds=timeoutSeconds;}

 Map<String,Object> create(long userId,OrderController.CreateOrder request,String key){if(key==null||key.isBlank())throw new BusinessException("TR40004","提交订单必须携带 Idempotency-Key");String requestHash=hash(request);Prepared prepared=tx.execute(status->prepare(userId,request,key,requestHash));if(prepared.replay())return detail(userId,prepared.orderNo());boolean reserved=false;try{List<Map<String,Object>> items=prepared.payload().items().stream().map(i->Map.<String,Object>of("merchantId",i.merchantId(),"shopId",i.shopId(),"skuId",i.skuId(),"quantity",i.quantity())).toList();Instant expires=Instant.now().plusSeconds(timeoutSeconds);List<StockAllocation> allocations=inventory.reserve(prepared.orderId(),prepared.orderNo(),prepared.payload().address().regionCode(),expires,items);reserved=true;tx.executeWithoutResult(s->activate(prepared,allocations,expires));}catch(BusinessException e){if(!reserved){if(e.code().contains("409")){tx.executeWithoutResult(s->failStock(prepared.orderId(),prepared.orderNo(),e.getMessage()));throw e;}tx.executeWithoutResult(s->schedule(prepared.orderNo(),"RESERVE_STOCK",e.getMessage()));return detail(userId,prepared.orderNo());}abortAfterReservation(prepared,e.getMessage());throw e;}catch(RuntimeException e){if(reserved)abortAfterReservation(prepared,e.getMessage());throw e;}return detail(userId,prepared.orderNo());}

 private Prepared prepare(long userId,OrderController.CreateOrder request,String key,String requestHash){Map<String,Object> existing=idempotency(key,userId);if(existing!=null){if(!requestHash.equals(existing.get("request_hash")))throw new BusinessException("TR40905","Idempotency-Key 已用于不同订单请求");return existingPrepared(String.valueOf(existing.get("result_ref")));}Map<String,Object> snapshot=jdbc.queryForMap("SELECT id,snapshot_json,status,result_order_no,expires_at FROM trade_checkout_snapshot WHERE checkout_token=? AND user_id=? FOR UPDATE",request.checkoutToken(),userId);if(((java.sql.Timestamp)snapshot.get("expires_at")).toInstant().isBefore(Instant.now()))throw new BusinessException("TR40904","结算凭证已过期，请重新结算");CheckoutPayload payload=checkout.payload(String.valueOf(snapshot.get("snapshot_json")));if(request.addressId()!=null&&!Objects.equals(request.addressId(),payload.address().addressId()))throw new BusinessException("TR40906","收货地址与结算快照不一致");if(snapshot.get("result_order_no")!=null){String result=String.valueOf(snapshot.get("result_order_no"));insertIdempotency(key,userId,requestHash,result);return existingPrepared(result);}long orderId=DistributedId.next();String orderNo="GM"+orderId;insertIdempotency(key,userId,requestHash,orderNo);jdbc.update("UPDATE trade_checkout_snapshot SET status='CONSUMED',result_order_no=?,consumed_at=CURRENT_TIMESTAMP WHERE id=?",orderNo,snapshot.get("id"));jdbc.update("INSERT INTO trade_order(id,order_no,user_id,total_amount,discount_amount,freight_amount,payable_amount,status,checkout_token,inventory_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'RESERVING',?,'RESERVING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",orderId,orderNo,userId,payload.totalAmount(),payload.discountAmount(),payload.freightAmount(),payload.payableAmount(),request.checkoutToken());Map<Long,Long> subIds=new HashMap<>();int index=1;for(CheckoutShopGroup group:payload.shopGroups()){long subId=DistributedId.next();subIds.put(group.shopId(),subId);String subNo=orderNo+"-"+index++;String remark=request.remarkByShop()==null?null:request.remarkByShop().get(String.valueOf(group.shopId()));jdbc.update("INSERT INTO trade_sub_order(id,sub_order_no,order_id,merchant_id,shop_id,shop_name,total_amount,discount_amount,payable_amount,status,remark,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'RESERVING',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",subId,subNo,orderId,group.merchantId(),group.shopId(),group.shopName(),group.totalAmount(),group.discountAmount(),group.payableAmount(),remark);}
 for(CheckoutItem item:payload.items()){long itemId=DistributedId.next();String skuJson=json(Map.of("skuId",item.skuId(),"skuCode",item.skuCode(),"unitPrice",item.unitPrice()));jdbc.update("INSERT INTO trade_order_item(id,order_id,sub_order_id,spu_id,sku_id,title,cover_url,sku_snapshot,quantity,unit_price,discount_amount,payable_amount,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",itemId,orderId,subIds.get(item.shopId()),item.spuId(),item.skuId(),item.title(),item.coverUrl(),skuJson,item.quantity(),item.unitPrice(),item.discountAmount(),item.payableAmount());}
 for(PromotionLine line:payload.promotionLines()==null?List.<PromotionLine>of():payload.promotionLines()){jdbc.update("INSERT INTO trade_order_discount(id,order_id,order_item_id,discount_type,source_id,amount,snapshot_json) VALUES(?,?,NULL,?,?,?,?)",DistributedId.next(),orderId,line.type(),line.sourceId(),line.amount(),json(Map.of("label",line.label())));}
 CheckoutAddress a=payload.address();jdbc.update("INSERT INTO trade_order_address(order_id,address_id,receiver,mobile,region_code,detail) VALUES(?,?,?,?,?,?)",orderId,a.addressId(),a.receiver(),a.mobile(),a.regionCode(),a.detail());if(payload.discountAmount().signum()>0)jdbc.update("INSERT INTO trade_discount_reservation(id,order_id,source_type,source_id,amount,status,created_at,updated_at) VALUES(?,?,?,?,?,'FROZEN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",DistributedId.next(),orderId,payload.discountType(),payload.discountSourceId(),payload.discountAmount());
 if(payload.userCouponId()!=null){BigDecimal couponAmt=(payload.promotionLines()==null?List.<PromotionLine>of():payload.promotionLines()).stream().filter(l->"COUPON".equals(l.type())).map(PromotionLine::amount).findFirst().orElse(BigDecimal.ZERO);if(couponAmt.signum()>0)marketing.freezeCoupon(orderNo,userId,payload.userCouponId(),couponAmt);}
 if(payload.pointsUsed()!=null&&payload.pointsUsed()>0)member.freezePoints(orderNo,userId,payload.pointsUsed());log(orderId,null,"RESERVING","USER",userId,"订单快照已创建，等待库存预占");return new Prepared(orderId,orderNo,payload,false);}

 private void activate(Prepared prepared,List<StockAllocation> allocations,Instant expires){int changed=jdbc.update("UPDATE trade_order SET status='PENDING_PAYMENT',inventory_status='RESERVED',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status IN ('RESERVING','RESERVATION_RETRY')",prepared.orderId());if(changed==0)return;jdbc.update("UPDATE trade_sub_order SET status='PENDING_PAYMENT',updated_at=CURRENT_TIMESTAMP WHERE order_id=?",prepared.orderId());for(StockAllocation a:allocations){Long subId=jdbc.queryForObject("SELECT sub_order_id FROM trade_order_item WHERE order_id=? AND sku_id=? LIMIT 1",Long.class,prepared.orderId(),a.skuId());jdbc.update("INSERT IGNORE INTO trade_fulfillment_plan(id,order_id,sub_order_id,warehouse_id,sku_id,quantity,status) VALUES(?,?,?,?,?,?,'RESERVED')",DistributedId.next(),prepared.orderId(),subId,a.warehouseId(),a.skuId(),a.quantity());}jdbc.update("INSERT INTO trade_order_timeout(id,order_id,timeout_type,execute_at,status,updated_at) VALUES(?,?,'PAYMENT',?,'PENDING',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE execute_at=VALUES(execute_at),status='PENDING',updated_at=CURRENT_TIMESTAMP",DistributedId.next(),prepared.orderId(),java.sql.Timestamp.from(expires));List<Long> cartIds=prepared.payload().items().stream().map(CheckoutItem::cartItemId).filter(id->id>0).toList();if(!cartIds.isEmpty())jdbc.update("DELETE FROM trade_cart_item WHERE id IN ("+String.join(",",Collections.nCopies(cartIds.size(),"?"))+")",cartIds.toArray());log(prepared.orderId(),"RESERVING","PENDING_PAYMENT","SYSTEM",0,"库存预占成功");events.append("TRADE_ORDER",prepared.orderNo(),"trade.order.created.v1",Map.of("orderId",prepared.orderId(),"orderNo",prepared.orderNo(),"payableAmount",prepared.payload().payableAmount()));jdbc.update("UPDATE trade_compensation_task SET status='SUCCESS',updated_at=CURRENT_TIMESTAMP WHERE task_type='RESERVE_STOCK' AND business_no=?",prepared.orderNo());}
 private void failStock(long orderId,String orderNo,String reason){jdbc.update("UPDATE trade_order SET status='CANCELLED',inventory_status='RELEASED',closed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status IN ('RESERVING','RESERVATION_RETRY')",orderId);jdbc.update("UPDATE trade_sub_order SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE order_id=?",orderId);jdbc.update("UPDATE trade_discount_reservation SET status='RELEASED',updated_at=CURRENT_TIMESTAMP WHERE order_id=? AND status='FROZEN'",orderId);releasePromotions(orderNo);log(orderId,"RESERVING","CANCELLED","SYSTEM",0,reason);events.append("TRADE_ORDER",orderNo,"trade.order.cancelled.v1",Map.of("orderNo",orderNo,"reason","STOCK_FAILED"));}
 /** Reservation succeeded but activate failed: cancel order + release locked stock immediately (or schedule RELEASE_STOCK). */
 private void abortAfterReservation(Prepared prepared,String reason){tx.executeWithoutResult(s->failStock(prepared.orderId(),prepared.orderNo(),reason==null?"ACTIVATE_FAILED":reason));try{inventory.release(prepared.orderNo());}catch(Exception ex){schedule(prepared.orderNo(),"RELEASE_STOCK",ex.getMessage());jdbc.update("UPDATE trade_order SET inventory_status='RELEASE_PENDING',updated_at=CURRENT_TIMESTAMP WHERE order_no=? AND status='CANCELLED'",prepared.orderNo());}}
 void resumeReservation(String orderNo){Map<String,Object> order=internalOrder(orderNo);String status=String.valueOf(order.get("status"));if(!Set.of("RESERVING","RESERVATION_RETRY").contains(status))return;long orderId=number(order.get("id"));CheckoutPayload payload=checkout.payload(jdbc.queryForObject("SELECT snapshot_json FROM trade_checkout_snapshot WHERE checkout_token=?",String.class,order.get("checkout_token")));Prepared prepared=new Prepared(orderId,orderNo,payload,false);List<Map<String,Object>> items=jdbc.queryForList("SELECT s.merchant_id AS merchantId,s.shop_id AS shopId,i.sku_id AS skuId,i.quantity FROM trade_order_item i JOIN trade_sub_order s ON s.id=i.sub_order_id WHERE i.order_id=?",orderId);String region=jdbc.queryForObject("SELECT region_code FROM trade_order_address WHERE order_id=?",String.class,orderId);boolean reserved=false;try{List<StockAllocation> allocations=inventory.reserve(orderId,orderNo,region,Instant.now().plusSeconds(timeoutSeconds),items);reserved=true;tx.executeWithoutResult(s->activate(prepared,allocations,Instant.now().plusSeconds(timeoutSeconds)));}catch(BusinessException e){if(!reserved){if(e.code().contains("409"))tx.executeWithoutResult(s->failStock(orderId,orderNo,e.getMessage()));else throw e;return;}abortAfterReservation(prepared,e.getMessage());throw e;}catch(RuntimeException e){if(reserved)abortAfterReservation(prepared,e.getMessage());throw e;}}

 void cancel(long userId,String orderNo,String operator){boolean release=Boolean.TRUE.equals(tx.execute(s->{Map<String,Object> order=userId==0?internalOrderForUpdate(orderNo):ownForUpdate(userId,orderNo);long id=number(order.get("id"));String current=String.valueOf(order.get("status"));if("CANCELLED".equals(current))return false;if(!"PENDING_PAYMENT".equals(current))throw new BusinessException("TR40907","当前订单状态不可取消");int changed=jdbc.update("UPDATE trade_order SET status='CANCELLED',inventory_status='RELEASE_PENDING',version=version+1,closed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PENDING_PAYMENT'",id);if(changed==0)throw new BusinessException("TR40908","订单状态已变化，请刷新后重试");jdbc.update("UPDATE trade_sub_order SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE order_id=?",id);jdbc.update("UPDATE trade_order_timeout SET status='COMPLETED',updated_at=CURRENT_TIMESTAMP WHERE order_id=?",id);jdbc.update("UPDATE trade_discount_reservation SET status='RELEASED',updated_at=CURRENT_TIMESTAMP WHERE order_id=? AND status='FROZEN'",id);releasePromotions(orderNo);if(orderNo.startsWith("SK"))seckillOrders.onTimeoutCancel(orderNo);log(id,current,"CANCELLED",operator,userId,"订单取消并释放库存优惠");events.append("TRADE_ORDER",orderNo,"trade.order.cancelled.v1",Map.of("orderNo",orderNo,"reason",operator));return true;}));if(!release)return;try{inventory.release(orderNo);jdbc.update("UPDATE trade_order SET inventory_status='RELEASED',updated_at=CURRENT_TIMESTAMP WHERE order_no=? AND status='CANCELLED'",orderNo);}catch(BusinessException e){schedule(orderNo,"RELEASE_STOCK",e.getMessage());}}

 List<Map<String,Object>> orders(long userId,String status){String sql="SELECT order_no AS orderNo,total_amount AS totalAmount,discount_amount AS discountAmount,freight_amount AS freightAmount,payable_amount AS payableAmount,paid_amount AS paidAmount,status,inventory_status AS inventoryStatus,created_at AS createdAt,paid_at AS paidAt,closed_at AS closedAt FROM trade_order WHERE user_id=?";return status==null||status.isBlank()?jdbc.queryForList(sql+" ORDER BY created_at DESC",userId):jdbc.queryForList(sql+" AND status=? ORDER BY created_at DESC",userId,status);}
 Map<String,Object> detail(long userId,String orderNo){Map<String,Object> order=userId==0?internalOrder(orderNo):own(userId,orderNo);long id=number(order.get("id"));List<Map<String,Object>> subs=jdbc.queryForList("SELECT id,sub_order_no AS subOrderNo,merchant_id AS merchantId,shop_id AS shopId,shop_name AS shopName,total_amount AS totalAmount,discount_amount AS discountAmount,payable_amount AS payableAmount,status,remark FROM trade_sub_order WHERE order_id=? ORDER BY sub_order_no",id);for(Map<String,Object> sub:subs){long subId=number(sub.get("id"));sub.put("items",jdbc.queryForList("SELECT id,spu_id AS spuId,sku_id AS skuId,title,cover_url AS coverUrl,sku_snapshot AS skuSnapshot,quantity,unit_price AS unitPrice,discount_amount AS discountAmount,payable_amount AS payableAmount FROM trade_order_item WHERE sub_order_id=? ORDER BY id",subId));sub.put("fulfillmentPlans",jdbc.queryForList("SELECT warehouse_id AS warehouseId,sku_id AS skuId,quantity,status FROM trade_fulfillment_plan WHERE sub_order_id=? ORDER BY warehouse_id,sku_id",subId));}order.put("subOrders",subs);order.put("address",jdbc.queryForMap("SELECT address_id AS addressId,receiver,mobile,region_code AS regionCode,detail FROM trade_order_address WHERE order_id=?",id));order.put("discounts",jdbc.queryForList("SELECT discount_type AS discountType,source_id AS sourceId,amount FROM trade_order_discount WHERE order_id=?",id));order.put("payments",jdbc.queryForList("SELECT payment_no AS paymentNo,channel,amount,status,channel_trade_no AS channelTradeNo,created_at AS createdAt,paid_at AS paidAt FROM trade_payment WHERE order_id=? ORDER BY created_at DESC",id));order.remove("id");order.remove("user_id");order.remove("checkout_token");return order;}

 private Map<String,Object> own(long userId,String no){var rows=jdbc.queryForList("SELECT id,order_no AS orderNo,user_id,total_amount AS totalAmount,discount_amount AS discountAmount,freight_amount AS freightAmount,payable_amount AS payableAmount,paid_amount AS paidAmount,status,inventory_status AS inventoryStatus,checkout_token,created_at AS createdAt,updated_at AS updatedAt,paid_at AS paidAt,closed_at AS closedAt FROM trade_order WHERE order_no=? AND user_id=?",no,userId);if(rows.isEmpty())throw new BusinessException("TR40404","订单不存在");return rows.getFirst();}private Map<String,Object> ownForUpdate(long userId,String no){var rows=jdbc.queryForList("SELECT * FROM trade_order WHERE order_no=? AND user_id=? FOR UPDATE",no,userId);if(rows.isEmpty())throw new BusinessException("TR40404","订单不存在");return rows.getFirst();}private Map<String,Object> internalOrder(String no){var rows=jdbc.queryForList("SELECT id,order_no AS orderNo,user_id,total_amount AS totalAmount,discount_amount AS discountAmount,freight_amount AS freightAmount,payable_amount AS payableAmount,paid_amount AS paidAmount,status,inventory_status AS inventoryStatus,checkout_token,created_at AS createdAt,updated_at AS updatedAt,paid_at AS paidAt,closed_at AS closedAt FROM trade_order WHERE order_no=?",no);if(rows.isEmpty())throw new BusinessException("TR40404","订单不存在");return rows.getFirst();}private Map<String,Object> internalOrderForUpdate(String no){return jdbc.queryForMap("SELECT * FROM trade_order WHERE order_no=? FOR UPDATE",no);}
 private Prepared existingPrepared(String orderNo){Map<String,Object> order=internalOrder(orderNo);String json=jdbc.queryForObject("SELECT snapshot_json FROM trade_checkout_snapshot WHERE checkout_token=?",String.class,order.get("checkout_token"));return new Prepared(number(order.get("id")),orderNo,checkout.payload(json),true);}private Map<String,Object> idempotency(String key,long userId){var rows=jdbc.queryForList("SELECT request_hash,result_ref FROM trade_idempotency WHERE idempotency_key=? AND user_id=? AND business_type='CREATE_ORDER'",key,userId);return rows.isEmpty()?null:rows.getFirst();}private void insertIdempotency(String key,long userId,String hash,String result){try{jdbc.update("INSERT INTO trade_idempotency(idempotency_key,user_id,business_type,request_hash,result_ref,expires_at,created_at) VALUES(?,?,'CREATE_ORDER',?,?,?,CURRENT_TIMESTAMP)",key,userId,hash,result,java.sql.Timestamp.from(Instant.now().plusSeconds(86400)));}catch(DuplicateKeyException e){Map<String,Object> old=idempotency(key,userId);if(old==null||!hash.equals(old.get("request_hash")))throw new BusinessException("TR40905","Idempotency-Key 已用于不同订单请求");}}
 void schedule(String businessNo,String type,String error){jdbc.update("INSERT INTO trade_compensation_task(id,task_type,business_no,payload_json,status,next_retry_at,last_error,created_at,updated_at) VALUES(?,?,?,'{}','PENDING',CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE status='PENDING',next_retry_at=CURRENT_TIMESTAMP,last_error=VALUES(last_error),updated_at=CURRENT_TIMESTAMP",DistributedId.next(),type,businessNo,error);if("RESERVE_STOCK".equals(type))jdbc.update("UPDATE trade_order SET status='RESERVATION_RETRY',updated_at=CURRENT_TIMESTAMP WHERE order_no=? AND status='RESERVING'",businessNo);}
 private void log(long id,String from,String to,String type,long operator,String detail){jdbc.update("INSERT INTO trade_order_log(id,order_id,from_status,to_status,operator_type,operator_id,detail,created_at) VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",DistributedId.next(),id,from,to,type,operator,detail);}private String hash(Object value){try{return CheckoutService.sha256(mapper.writeValueAsString(value));}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private static long number(Object v){return ((Number)v).longValue();}
 private void releasePromotions(String orderNo){try{marketing.settleCoupon(orderNo,"release");}catch(Exception ignored){}try{member.settlePoints(orderNo,"release");}catch(Exception ignored){}}
 record Prepared(long orderId,String orderNo,CheckoutPayload payload,boolean replay){}
}
